                              if (f.ppsfMin !== undefined) setPpsfMin(f.ppsfMin);
                              if (f.ppsfMax !== undefined) setPpsfMax(f.ppsfMax);
                              if (f.dataSource) setDataSourceFilter(f.dataSource);
